class TransactionsListQuery(TypedDict, total=False):
    """Optional query parameters of `Transactions.list()` (`GET /api/v1/transactions`)."""

    domainUuid: str
    """Only transactions recorded for this domain ID"""
    serviceType: Literal["system", "admin", "user", "api"]
    """Only this service type. Who started the transaction: system (domain operations such as registration,
    renewal, transfer, delete refunds), admin (manual adjustment, deposit or withdrawal by LETO), user
    (deposit you paid), api.
    """
    serviceAction: Literal[
        "registration", "renewal", "transfer", "refund", "deposit", "withdrawal", "adjustment", "fee", "commission"
    ]
    """Only this service action. What the money was for: registration, renewal, transfer, refund, deposit,
    withdrawal, adjustment, fee (for example domain restore and other fees), commission.
    """
    type: Literal["charge", "refund", "credited", "debited", "adjustment"]
    """Only this type. Direction: charge (taken from the balance for a service), refund (returned for an
    earlier charge), credited (added, for example a deposit), debited (taken, for example a withdrawal),
    adjustment.
    """
    startDate: str
    """Start of the creation time range, inclusive (ISO 8601 date or date-time). Can be sent without
    endDate.
    """
    endDate: str
    """End of the creation time range, inclusive (ISO 8601). Can be sent without startDate. A date without
    a time (YYYY-MM-DD) includes the whole day.
    """
    page: int
    """Page number, starting at 1. Default 1. List only."""
    limit: int
    """Page size, 1 to 100. Default 20; larger values are capped at 100 on GET /transactions. `size` is
    accepted as an alias (`limit` wins when both are sent). List only.
    """
    size: int
    """Alias of `limit`, for clients that use `size` like the other lists. Used only when `limit` is not
    sent.
    """


